package calc

import (
	"fmt"
	"strings"
)

// spellStatusApplicationNode is 0x54d5c0 (cdecl, void): a spell context (arg1)
// tries to inflict status arg2 with chance arg3 (percent) and penalty arg4 on
// every character, then every monster, listed in it, and reports the result.
//
// Context fields: +0 spell id (realm = the u32 at [0x65be1c] + spell*0x1bf +
// 0x133), +0x5c source record, +0xc8 strength, +0xd0 level, +0xd4 bonus
// percent, +0xd8 base duration, +0xdc duration per level, +0xe4 monster count
// (i32) with ids at *(+0xec), +0xf4 character count (i32) with party indexes at
// *(+0xfc), result bytes +0x124/+0x125. Byte 0x68510c ("silent") is read once.
//
// Per target, in list order:
//   - R(100) >= chance (u32) skips it;
//   - d = perLevel*level + base (u32 wrap); unless d == 9999: d++, R(4): 0
//     with d > 1 or 1 with d <= 2 adds 1, then 0x517f90 adds u32(d*bonus)/100;
//   - the target record is {kind, index, id} on 0x54d5c0's stack: a character
//     sets {1, index} (index -1 asserts, block 54d67e) and keeps the old id (0
//     on a fresh stack); a monster sets {3, id of the record found by
//     0x4e5550(..., id, 1)/0x4e5620} and keeps the last character index;
//   - spell 0x1d with a running buff 5 (character +0xaa9, monster +0xeb, value
//     v != 0): e = d - v; a character runs 0x523b30(index, 5, d) (return
//     ignored), a monster 0x524400(id, 5, d): v > d subtracts d, else the
//     slot's three dwords clear, 0x4acd80(visual, 0x15, 0) and the 0x50e8c0
//     rebuild run. e <= 0 (i32) ends the target; else 0x551ba0(source, target,
//     status, realm, strength, penalty, e, silent, silent, 0) and a zero low
//     byte with silent 0 counts the target;
//   - otherwise 0x551ba0(..., d, silent, silent, 0); a nonzero low byte ends
//     the target. Spell 0xe on a character adds 0x551ba0(source, target, 0x11,
//     spell 14's realm, strength>>1, penalty, d>>1, 0, silent, 0); spell 0xe or
//     0x1e on a monster adds 0x551ba0(..., status, realm, strength>>1, penalty,
//     d>>1, 0, silent, 0); both returns are ignored. Silent 0 counts the target.
//
// With silent 0 and a nonzero count: an open message box (byte 0x69b7b8, read
// by 0x5905e0) gets 0x5905f0(+0x124 ? 0x619794 : 0x619788, -1) and 0x5905c0(1,
// -1) (sets 0x69b7b8 = 1). The text ids are the u16 pair at exe 0x61e572 +
// 8*status (first, second), strings at [0x68c09c] + 4*id. Exactly one target in
// both lists (u32 sum == 1) prints "%s %s" (0x617584) with the character name
// (+5) or the monster name (0x4e5840 then 0x4e5150) and the first text; else
// "%ld %s" (0x619778) with 1 and the first text when the count is 1, or the
// count and the second text. 0x517a90 formats into 0x689fd0, then
// 0x5905f0(0x689fd0, -1), 0x5905c0(1, -1) and +0x124 = +0x125 = 1.
//
// Address stubs (re/emu/cases/0054d5c0.json): D4 0x551ba0 (call k returns
// resistResult_k), 0x523b30 (returns ignoredReturn; the caller ignores eax);
// 排除 0x4acd80, 0x5905f0, 0x5182e0 (the name log in 0x4e5150). Outputs are
// their call counts and every call's recorded arguments, the message bytes,
// the formatted text and each monster's buff 5 and rebuild fields.
//
// Emu replays the stubs. F runs statusImmunityAndResistNode on the F-only block
// f.* (0x551ba0's inputs from its matchSlot on, with the message byte set to
// silent) and characterEffectDecayNode on the F-only block g.* (0x523b30's
// inputs other than party slot, buff 5 duration, buff index and amount); each
// character keeps its own decay state, the refresh bytes are shared, and the
// new buff 5 duration is written back to +0xaa9.
//
// Asserts (calc panics): character index -1 (cov-exempt 54d67e), monster id
// missing (0x4e5550), null monster record (cov-exempt 54d8bb). Unreachable:
// 54d892 (list index past the count inside the loop), 54db40 (one target with
// a kind other than 1 or 3). Fixture caps (panics): spell id < 256, status <
// 20 (the text-id pairs; call sites pass 3..0x12), list counts <= 8, party
// indexes 0..7 where read, monster ids 100..107, text ids < 920.
func spellStatusApplicationNode(in []int64, r Rand) []int64 { return sapRun(in, r, true) }

func init() {
	Nodes["0054d5c0"] = Node{Addr: "0054d5c0", In: sapIn, Out: sapOut, F: spellStatusApplicationNode,
		Emu: func(in []int64, r Rand) []int64 { return sapRun(in, r, false) }}
}

const (
	sapCtx      = 0x20000000 // the case's argument (object ctx)
	sapInSpell  = 0          // sapIn index of spell
	sapF        = 100        // sapIn index of the first f.* input
	sapSpells   = 256        // fixture spell records
	sapStatuses = 20         // text-id pairs at 0x61e572 used by the call sites
	sapTargets  = 8          // fixture list entries
	sapTexts    = 920        // fixture string table entries
	sapFixed    = 9999       // duration that skips the roll (0x54d617)
	sapBox      = 0x69b7b8   // message box open byte (0x5905e0 / 0x5905c0)
	sapBuf      = 0x689fd0   // 0x517a90's output buffer
	sapPair     = 0x61e572   // exe table: u16 text id pair per status, stride 8
	sapNone     = 0xffffffff
)

var sapG = sapF + len(sirIn) - sirSlot // sapIn index of the first g.* input

// sapDecaySkip are the 0x523b30 inputs the call supplies (not in g.*).
var sapDecaySkip = map[int]bool{0: true, 115: true, 348: true, 349: true}

func sapCall(w *mcaWorld, a uint32, args ...uint32) uint32 {
	s := sapStubs[a]
	k := w.u32(s.cnt)
	for _, r := range s.rec {
		if k >= r[3] {
			panic(fmt.Sprintf("spell status application: stub %#x called more than %d times (fixture record cap)", a, r[3]))
		}
		w.put(r[2]+k*r[1], int(r[1]), uint64(args[r[0]-1]))
	}
	w.put(s.cnt, 4, uint64(k+1))
	return k
}

// sapFormat is swprintf for the two fixture formats: %s, %ld.
func sapFormat(w *mcaWorld, f uint32, args ...uint32) string {
	var b strings.Builder
	s := []rune(srdWstr(w, f))
	for i := 0; i < len(s); i++ {
		if s[i] != '%' {
			b.WriteRune(s[i])
			continue
		}
		if len(args) == 0 {
			panic("spell status application: format directive outside the fixture texts")
		}
		switch {
		case i+1 < len(s) && s[i+1] == 's':
			b.WriteString(srdWstr(w, args[0]))
			i++
		case i+2 < len(s) && s[i+1] == 'l' && s[i+2] == 'd':
			fmt.Fprint(&b, int32(args[0]))
			i += 2
		default:
			panic("spell status application: format directive outside the fixture texts")
		}
		args = args[1:]
	}
	return b.String()
}

// sapName is 0x4e5150(m, 0, 0).
func sapName(w *mcaWorld, m uint32) uint32 {
	t := w.template(m)
	if w.u16(t+0x187) == 0x18d {
		srdPutW(w, 0x6875c3, sapFormat(w, 0x614b44, w.charBase(w.u32(0x6875ef))+5))
		return 0x6875c3
	}
	if w.u32(m+4) == 0 {
		if !w.act15(w.u32(m + 0xc)) {
			sapCall(w, 0x5182e0, 1, 0x614b20, w.u32(m))
		}
		return t + 0x60
	}
	if w.u8(w.group(w.u32(m+4))+0x2c) == 0 {
		return t + 0x60
	}
	return t
}

// sapCancel is 0x524400(id, 5, d).
func sapCancel(w *mcaWorld, id, d uint32) {
	m := w.findMonster(id)
	if s := w.u32(m + 0xeb); s > d {
		w.put(m+0xeb, 4, uint64(s-d))
		return
	}
	w.put(m+0xe3, 4, 0)
	w.put(m+0xe7, 4, 0)
	w.put(m+0xeb, 4, 0)
	sapCall(w, 0x4acd80, w.u32(m+0xc), 0x15, 0)
	w.rebuild(id)
}

func sapRun(in []int64, r Rand, real bool) []int64 {
	if len(in) != len(sapIn) {
		panic("spell status application: wrong input count")
	}
	if uint64(in[sapInSpell]) >= sapSpells {
		panic("spell status application: spell id past the fixture's 256 records")
	}
	return mcaRun(&sapSpec, real, func(w *mcaWorld) { sapBody(w, in) })(in, r)
}

func sapBody(w *mcaWorld, in []int64) {
	const ctx = sapCtx
	silent := uint32(w.u8(0x68510c))
	status, chance, penalty := mcaArg(w, 1), mcaArg(w, 2), mcaArg(w, 3)
	if status >= sapStatuses {
		panic("spell status application: status past the text-id table's 20 entries")
	}
	chars, mons := int32(w.u32(ctx+0xf4)), int32(w.u32(ctx+0xe4))
	if chars > sapTargets || mons > sapTargets {
		panic("spell status application: list count past the fixture's 8")
	}
	spell, strength := w.u32(ctx), w.u32(ctx+0xc8)
	spells := w.u32(0x65be1c)
	realm := w.u32(spells + spell*0x1bf + 0x133)
	var count, kind, tIdx, tID uint32 // the target record is never cleared (fresh stack: 0)
	roll := func() (uint32, bool) {
		if uint32(w.r.R(100)) >= chance {
			return 0, false
		}
		d := w.u32(ctx+0xdc)*w.u32(ctx+0xd0) + w.u32(ctx+0xd8)
		if d != sapFixed {
			d++
			if x := w.r.R(4); x == 0 && d > 1 || x == 1 && d <= 2 {
				d++
			}
			d += d * w.u32(ctx+0xd4) / 100 // 0x517f90
		}
		return d, true
	}
	resist := func(st, rl, str, d, msg uint32) byte {
		args := make([]uint32, 21)
		copy(args, []uint32{ctx + 0x5c, 0, st, rl, str, penalty, d, msg, silent, 0})
		args[18], args[19], args[20] = kind, tIdx, tID
		k := sapCall(w, 0x551ba0, args...)
		if !w.real {
			s := sapStubs[0x551ba0]
			if k >= s.retN {
				panic("spell status application: 0x551ba0 return past its values")
			}
			return w.u8(s.ret + 4*k)
		}
		v := make([]int64, len(sirIn))
		v[sirStatus], v[sirRealm], v[sirStrength], v[sirPenalty], v[sirDuration] = int64(st), int64(rl), int64(str), int64(penalty), int64(d)
		v[sirMessage], v[sirDurMessage], v[sirDurFlagB] = int64(msg), int64(silent), 0
		v[sirSrcKind], v[sirSrcIndex] = int64(w.u32(ctx+0x5c)), int64(int32(w.u32(ctx+0x60)))
		v[sirKind], v[sirIdx], v[sirMonID] = int64(kind), int64(int32(tIdx)), int64(tID)
		copy(v[sirSlot:], in[sapF:sapG])
		v[sirMsgEnabled] = int64(silent)
		return byte(statusImmunityAndResistNode(v, w.r)[0])
	}
	decayState := map[uint32][]int64{}
	var refresh []int64 // 0x523b30's shared refresh byte and masks (in 352..354)
	decay := func(idx, d uint32) {
		sapCall(w, 0x523b30, idx, 5, d)
		if !w.real {
			return // eax ignored
		}
		v, ok := decayState[idx]
		if !ok {
			v = make([]int64, 612)
			g := in[sapG:]
			for i := range v {
				if !sapDecaySkip[i] {
					v[i], g = g[0], g[1:]
				}
			}
			if refresh == nil {
				refresh = append([]int64(nil), v[352:355]...)
			}
		}
		copy(v[352:355], refresh)
		c := w.charBase(idx)
		v[0], v[115], v[348], v[349] = int64(idx), int64(w.u32(c+0xaa9)), 5, int64(d)
		out := characterEffectDecayNode(v, w.r)
		copy(v[98:122], out[0:24])
		v[350] = out[24]
		copy(refresh, out[25:28])
		copy(v[355:], out[28:])
		decayState[idx] = v
		w.put(c+0xaa9, 4, uint64(out[17]))
	}
	for k := int32(0); k < chars; k++ {
		d, ok := roll()
		if !ok {
			continue
		}
		idx := w.u32(w.u32(ctx+0xfc) + 4*uint32(k))
		if idx == sapNone {
			panic("spell status application: character index -1 (assert at 0x54d67e)")
		}
		kind, tIdx = 1, idx
		if spell == 0x1d {
			if v := w.u32(w.charBase(idx) + 0xaa9); v != 0 {
				e := d - v
				decay(idx, d)
				if int32(e) > 0 && resist(status, realm, strength, e, silent) == 0 && silent == 0 {
					count++
				}
				continue
			}
		}
		if resist(status, realm, strength, d, silent) != 0 {
			continue
		}
		if spell == 0xe {
			resist(0x11, w.u32(spells+0x19a5), strength>>1, d>>1, 0) // spell 14's realm
		}
		if silent == 0 {
			count++
		}
	}
	for k := int32(0); k < mons; k++ {
		d, ok := roll()
		if !ok {
			continue
		}
		m := w.findMonster(w.u32(w.u32(ctx+0xec) + 4*uint32(k))) // 0x4e5550 (asserts on a missing id), 0x4e5620
		kind, tID = 3, w.u32(m)
		if spell == 0x1d {
			if v := w.u32(m + 0xeb); v != 0 {
				e := d - v
				sapCancel(w, tID, d)
				if int32(e) > 0 && resist(status, realm, strength, e, silent) == 0 && silent == 0 {
					count++
				}
				continue
			}
		}
		if resist(status, realm, strength, d, silent) != 0 {
			continue
		}
		if spell == 0xe || spell == 0x1e {
			resist(status, realm, strength>>1, d>>1, 0)
		}
		if silent == 0 {
			count++
		}
	}
	if silent != 0 || count == 0 {
		return
	}
	if w.u8(sapBox) != 0 {
		t := uint32(0x619788)
		if w.u8(ctx+0x124) != 0 {
			t = 0x619794
		}
		sapCall(w, 0x5905f0, t, sapNone)
		w.put(sapBox, 1, 1)
	}
	text := func(second uint32) uint32 {
		id := w.u16(sapPair + 2*second + 8*status)
		if id >= sapTexts {
			panic("spell status application: text id past the fixture's 920 strings")
		}
		return w.u32(w.u32(0x68c09c) + 4*id)
	}
	var s string
	switch one := uint32(mons)+uint32(chars) == 1; {
	case one && kind == 1:
		s = sapFormat(w, 0x617584, w.charBase(tIdx)+5, text(0))
	case one && kind == 3:
		s = sapFormat(w, 0x617584, sapName(w, w.findMonster(tID)), text(0))
	case one:
		panic("spell status application: one target of kind other than 1 or 3 (block 54db40, unreachable)")
	case count == 1:
		s = sapFormat(w, 0x619778, 1, text(0))
	default:
		s = sapFormat(w, 0x619778, count, text(1))
	}
	srdPutW(w, sapBuf, s)
	sapCall(w, 0x5905f0, sapBuf, sapNone)
	w.put(sapBox, 1, 1)
	w.put(ctx+0x124, 1, 1)
	w.put(ctx+0x125, 1, 1)
}

